 public static synchronized JSONObject install(){JSONObject out=new JSONObject();JSONArray failures=new JSONArray();int declared=0,installed=0,blocked=0;try{for(String raw:RAW){JSONObject r=Xmm2025SourceIndex.enrich(new JSONObject(raw));String id=r.optString("id");JSONObject basis=r.optJSONObject("mechanical_basis");String locator=basis==null?"":basis.optString("source_locator");JSONObject d=AuthorizedBestiaryScopeEngine.declare(new JSONObject().put("id",id).put("source_book",SOURCE_BOOK).put("source_locator",locator));if(d.optBoolean("accepted"))declared++;else{blocked++;failures.put(new JSONObject().put("id",id).put("stage","scope"));continue;}try{CompiledStatblockEngine.registerAuthorized(r);installed++;}catch(Exception e){blocked++;failures.put(new JSONObject().put("id",id).put("stage","register").put("reason",e.getMessage()==null?"blocked":e.getMessage()));}}return out.put("source",SOURCE_ID).put("expected",EXPECTED).put("scope_declared",declared).put("statblocks_installed",installed).put("blocked",blocked).put("complete",declared==EXPECTED&&installed==EXPECTED&&blocked==0).put("auto_rolls",false).put("failures",failures);}catch(Exception e){try{return out.put("source",SOURCE_ID).put("expected",EXPECTED).put("statblocks_installed",installed).put("blocked",EXPECTED-installed).put("complete",false).put("status","blocked_runtime_error");}catch(Exception ignored){return out;}}}
 public static synchronized JSONObject coverage(){JSONObject i=install();int tactical=0,actionless=0;JSONArray incomplete=new JSONArray();try{for(String raw:RAW){JSONObject r=new JSONObject(raw);String id=r.optString("id");JSONObject p=CompiledStatblockEngine.runtimeProfile(id);JSONObject c=p.optJSONObject("completeness");if(c!=null&&c.optBoolean("tactical",false))tactical++;else incomplete.put(id);if(r.optBoolean("source_actionless",false))actionless++;}return new JSONObject().put("source",SOURCE_ID).put("expected",EXPECTED).put("installed",i.optInt("statblocks_installed")).put("blocked",i.optInt("blocked")).put("tactical_runtime",tactical).put("source_actionless",actionless).put("pending",EXPECTED-i.optInt("statblocks_installed")).put("complete",i.optBoolean("complete")&&tactical==EXPECTED).put("full_automation_claim",false).put("auto_rolls",false).put("incomplete",incomplete);}catch(Exception e){return i;}}
 public static synchronized JSONObject statblock(String name){install();JSONObject p=CompiledStatblockEngine.runtimeProfile(name);try{return new JSONObject().put("source",SOURCE_ID).put("name",name==null?"":name).put("resolved",p.optBoolean("found",false)).put("auto_rolls",false).put("result",p);}catch(Exception e){return new JSONObject();}}
 public static synchronized JSONObject catalog(){JSONArray names=new JSONArray();try{for(String raw:RAW)names.put(new JSONObject(raw).optString("id"));return new JSONObject().put("source",SOURCE_ID).put("count",names.length()).put("names",names).put("auto_rolls",false);}catch(Exception e){return new JSONObject();}}
 public static JSONObject source(String id){return Xmm2025SourceIndex.get(id);}
 public static JSONObject search(String kind,String value){try{return Xmm2025SourceIndex.filter(kind,value);}catch(Exception e){return new JSONObject();}}
 public static synchronized JSONObject dependencyCoverage(){install();return XmmDependencyRuntimeEngine.dependencyCoverage();}
